head.script:
scwin.trigger1_onclick = function(e) {
    $w.executeSubmission("submission1");
};
scwin.trigger2_onclick = function(e) {
    WebSquare.ModelUtil.abort("submission1");
};
scwin.submission1_submitdone = function(e) {
    //alert("완료");
    //log = "완료";
    localStorage.setItem("log", "완료");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 2. 네트워크탭으로 이동해 브라우저에서 submit 버튼을 클릭한다.
    //2. Go to the Network tab and click the submit button in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "6000");
    //Verify 2. 5초 뒤 submit 이 동작해서 완료 팝업이 생성된다.
    //2. After 5 seconds, the submit pops up.
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == '완료'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. abort 버튼을 클릭한다.
    //3. Click the abort button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log')");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    var log;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Mar-2018
    //End unitTest

}
